.equ __NR_exit, 60

.section .text
.global _start
.type _start, @function
_start:
    xor %r12d, %r12d

    /* CALL must preserve an input flag when a transparent callee returns. */
    clc
    mov $-1, %eax
    add $1, %eax
    call direct_transparent
    jc .Ldirect_transparent_ok
    or $1, %r12d
.Ldirect_transparent_ok:

    /* The caller observes carry generated by the callee before RET. */
    clc
    call direct_sets_cf
    jc .Ldirect_ret_ok
    or $2, %r12d
.Ldirect_ret_ok:

    /* A callee definition kills the incoming carry and supplies a new one. */
    stc
    mov $-1, %eax
    add $1, %eax
    call direct_clears_cf
    jnc .Ldirect_overwrite_ok
    or $4, %r12d
.Ldirect_overwrite_ok:

    /* A callee may consume an incoming flag before defining any flags. */
    clc
    mov $-1, %eax
    add $1, %eax
    call direct_reads_cf

    /* One transparent callee can return to continuations needing two flags. */
    clc
    mov $-1, %eax
    add $1, %eax
    call shared_transparent
    jc .Lshared_cf_ok
    or $16, %r12d
.Lshared_cf_ok:
    mov $1, %eax
    sub $1, %eax
    call shared_transparent
    jz .Lshared_zf_ok
    or $16, %r12d
.Lshared_zf_ok:

    /* An indirect JMP is not necessarily an ABI function boundary. */
    clc
    mov $-1, %eax
    add $1, %eax
    lea .Lindirect_jmp_target(%rip), %rax
    jmp *%rax
.Lindirect_jmp_target:
    jc .Lindirect_jmp_ok
    or $64, %r12d
.Lindirect_jmp_ok:

    mov %r12d, %edi
    mov $__NR_exit, %eax
    syscall
.size _start, .-_start

.type direct_transparent, @function
direct_transparent:
    mov %rcx, %rcx
    ret
.size direct_transparent, .-direct_transparent

.type direct_sets_cf, @function
direct_sets_cf:
    mov $-1, %eax
    add $1, %eax
    ret
.size direct_sets_cf, .-direct_sets_cf

.type direct_clears_cf, @function
direct_clears_cf:
    xor %eax, %eax
    ret
.size direct_clears_cf, .-direct_clears_cf

.type direct_reads_cf, @function
direct_reads_cf:
    jc .Ldirect_read_ok
    or $8, %r12d
.Ldirect_read_ok:
    ret
.size direct_reads_cf, .-direct_reads_cf

.type shared_transparent, @function
shared_transparent:
    mov %rdx, %rdx
    ret
.size shared_transparent, .-shared_transparent
